import random
import string
from typing import List

# This generator produces interesting regular expression patterns (ECMAScript flavor)
# suitable for std::regex construction. The fuzzer stub wraps construction in a try/catch
# and falls back to ".*" on failure, so we bias toward valid-but-diverse patterns while
# occasionally emitting edge/invalid ones to exercise the fallback.

MAX_LEN = 512

def _rand_choice(rng: random.Random, seq):
    return seq[rng.randrange(0, len(seq))]

def _char_class_chunk(rng: random.Random) -> str:
    # Build a valid character class with possible ranges and escapes
    # Ensure it contains at least one valid element and is closed
    parts: List[str] = []
    # optionally negate
    if rng.random() < 0.25:
        parts.append("^")
    # add 1-4 elements/ranges
    n = rng.randint(1, 4)
    for _ in range(n):
        t = rng.random()
        if t < 0.4:
            # single literal (avoid ']' and '-')
            c = _rand_choice(rng, string.ascii_letters + string.digits + "_ .,:;!@#$%&?/")
            if c in "]-\\":
                parts.append("\\" + c)
            else:
                parts.append(c)
        elif t < 0.75:
            # range a-b with a<=b
            a = _rand_choice(rng, string.ascii_lowercase)
            b = _rand_choice(rng, string.ascii_lowercase)
            if a > b:
                a, b = b, a
            if a == b:
                parts.append(a)
            else:
                parts.append(f"{a}-{b}")
        else:
            # escaped sequence
            esc = _rand_choice(rng, ["\\d", "\\D", "\\w", "\\W", "\\s", "\\S", "\\.", "\\-", "\\]", "\\["])
            parts.append(esc)
    return "[" + "".join(parts) + "]"

def _quantifier(rng: random.Random) -> str:
    r = rng.random()
    if r < 0.25:
        return "*" if rng.random() < 0.5 else "+"
    if r < 0.5:
        return "?"
    if r < 0.8:
        m = rng.randint(0, 5)
        n = rng.randint(m, m + rng.randint(0, 6))
        return "{" + f"{m},{n}" + "}"
    else:
        m = rng.randint(0, 6)
        return "{" + f"{m}" + "}"

def _literal_chunk(rng: random.Random) -> str:
    # mix of escaped and raw literals
    alph = string.ascii_letters + string.digits + " _.-:/@#,$%&;!"  # keep generally safe
    length = rng.randint(1, 6)
    s = []
    for _ in range(length):
        c = _rand_choice(rng, alph)
        if c in ".^$|?*+()[]{}\\":
            s.append("\\" + c)
        else:
            s.append(c)
    return "".join(s)

def _group(rng: random.Random, depth: int) -> str:
    # Build a nested group with alternations optionally
    if depth <= 0:
        return _literal_or_atom(rng, depth)
    parts = []
    num_alts = rng.randint(1, 3)
    for i in range(num_alts):
        seq_len = rng.randint(1, 3)
        seq = []
        for _ in range(seq_len):
            seq.append(_literal_or_atom(rng, depth - 1))
            if rng.random() < 0.35:
                seq[-1] += _quantifier(rng)
        parts.append("".join(seq))
    # choose group type: non-capturing or capturing
    prefix = "(?:" if rng.random() < 0.4 else "("
    return prefix + "|".join(parts) + ")"

def _atom(rng: random.Random) -> str:
    # An atom is one of: dot, anchor, char class, escaped class, literal
    r = rng.random()
    if r < 0.15:
        return "."
    if r < 0.3:
        return "^" if rng.random() < 0.5 else "$"
    if r < 0.6:
        return _char_class_chunk(rng)
    if r < 0.8:
        return _rand_choice(rng, ["\\d", "\\D", "\\w", "\\W", "\\s", "\\S"])
    return _literal_chunk(rng)

def _literal_or_atom(rng: random.Random, depth: int) -> str:
    return _atom(rng) if rng.random() < 0.6 else _group(rng, depth)

def _build_valid_pattern(rng: random.Random) -> str:
    # Compose a pattern with a variety of constructs
    parts: List[str] = []
    if rng.random() < 0.3:
        parts.append("^")
    seq_count = rng.randint(1, 4)
    for _ in range(seq_count):
        # choose between atom or group
        frag = _literal_or_atom(rng, depth=2)
        # attach optional quantifier
        if rng.random() < 0.5:
            frag += _quantifier(rng)
        parts.append(frag)
        # optional alternation between sequences
        if rng.random() < 0.3:
            parts.append("|")
    pat = "".join(parts).strip("|")
    if rng.random() < 0.3:
        pat += "$"
    return pat[:MAX_LEN]

def _build_glob_like(rng: random.Random) -> str:
    # Create a pattern that resembles a translated glob (still valid regex)
    # Use simple conversions: * -> .*, ? -> ., ranges and groups
    atoms = []
    n = rng.randint(3, 8)
    for _ in range(n):
        t = rng.random()
        if t < 0.3:
            atoms.append(".*")
        elif t < 0.45:
            atoms.append(".")
        elif t < 0.7:
            atoms.append(_char_class_chunk(rng))
        elif t < 0.85:
            # alternation like (foo|bar)
            a = _literal_chunk(rng)
            b = _literal_chunk(rng)
            atoms.append(f"(?:{a}|{b})")
        else:
            atoms.append(_literal_chunk(rng))
    return "".join(atoms)[:MAX_LEN]

def _build_edge_case(rng: random.Random) -> str:
    # Edge cases that are still often valid
    choices = [
        "",                      # empty pattern
        ".*",                   # match anything
        "^$",                   # matches empty line
        "(a|b|c)?",             # optional group
        "(?:\\w+)(?:\\s+\\w+)*",  # words sequence
        "[\n\r\t\f\v]",        # whitespace class via escapes
        "[A-Za-z0-9_]+",        # common word pattern
        "(.*)",                 # greedy capture
        "(.*?)",                # non-greedy (ECMAScript supports ? quantifier laziness)
        "^.*$",
    ]
    return _rand_choice(rng, choices)

def _build_potentially_invalid(rng: random.Random) -> str:
    # Some intentionally malformed patterns to trigger std::regex_error
    options = [
        "[abc",           # unclosed class
        "(abc",           # unclosed group
        "abc)",           # unmatched close
        "{3,2}",          # invalid quantifier range
        "\\",             # trailing escape
        "a{,3}",          # invalid lower bound
        "(?",             # bad group
    ]
    return _rand_choice(rng, options)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    kind = rng.random()
    if kind < 0.55:
        s = _build_valid_pattern(rng)
    elif kind < 0.75:
        s = _build_glob_like(rng)
    elif kind < 0.93:
        s = _build_edge_case(rng)
    else:
        s = _build_potentially_invalid(rng)
    # Ensure non-empty bytes to exercise code paths; if empty, return b""
    b = s.encode('utf-8', errors='ignore')
    if len(b) > 4096:
        b = b[:4096]
    return b
